import {defineTool} from '@deepseek-ai/dsh-tools';
import {CommandDefinitionId} from '@deepseek-ai/dsh-commands/brand';
import {blenderStatus,prepareBlender,startBlender} from './blender-runner.js';
import {assetSpecificationParameter} from './asset-specification.js';
import {requireProject} from './desktop.js';
export const name='qcoderi-studio3d';
export const inject=['tools','systemPrompt','jobs','commands'];
export const STUDIO_PROMPT=`Для задач по созданию и правке 3D делай реальные редактируемые объекты и проверяй их вид. Работай в выбранном пользователем приложении: Blender, Unreal, CAD, скульптинг или другом редакторе. Для Blender всегда предпочитай blender_status и blender_run (отдельный фоновый процесс без показа окон пользователю, с рендерами через share_image), а не GUI-запуск через desktop_launch. Для остальных GUI-редакторов desktop_launch по умолчанию запускает их на скрытом фоновом рабочем столе, а desktop_inspect/desktop_action управляют ими без переключения фокуса пользователя. Не устанавливай новые редакторы без поручения.
Сначала изучи пользовательские фото-референсы как изображения, существующие файлы и задачу. Для визуальной проверки нужна модель с поддержкой изображений; если выбранная модель текстовая, не утверждай, что видела фото или рендер: сообщи о необходимости выбрать модель с image-входом. Выдели силуэт, пропорции, материалы, масштаб и назначение объекта. Не заменяй референс общим примитивом. Если важны неизвестные вид сзади или размеры, задай один конкретный вопрос, а остальные части делай по разумным допущениям. Для 2D-концепта, текстуры или фона используй generate_image: Seedream для создания и Krea для одиночной правки; концепт не является готовой 3D-моделью.
Строй сначала читаемую основную форму и пропорции, затем функциональные детали, фаски и аккуратные переходы. Чистая геометрия: правильные нормали, отсутствие случайных пересечений/дублей/вырожденных полигонов, контролируемая плотность, адекватные масштабы и origin. Для деформации — подходящая топология; для hard-surface — фаски и корректный shading; для печати — замкнутость, толщина и реальные единицы. Нужность UV, ретопологии, LOD, коллизий и бюджета полигонов определяется назначением. Не применяй необратимо все модификаторы и не пересохраняй исходник без необходимости: сохраняй редактируемый результат новой версией.
Материалы должны различаться по roughness/metallic/цвету и масштабу текстур; избегай одинакового пластика на всех поверхностях. Для демонстрации подготовь камеру, нейтральный фон и читаемый свет key/fill/rim; проверь шум и клиппинг. В Blender-скрипте доступен qc: qc.material(...), qc.studio(subjects,quality='preview'|'final'), qc.audit(). Параметр blender_run views=true автоматически создаёт общий, передний, боковой и задний кадры; открой их через share_image и исправь замечания. QC_OUTPUT_DIR — папка текущего запуска. Blender работает отдельным процессом и не меняет несохранённую сцену открытого редактора; учитывай это перед открытием сохранённого результата.
Если quality_review есть в текущем каталоге инструментов, перед финальной передачей вызови quality_review с неизменным именем задачи, критериями, реальными изображениями результата и локальными референсами. Если референсы только в чате, сначала сохрани их в рабочую папку штатным инструментом. Проверяющий использует выбранную модель; он не выполняет правки. Исправь обоснованные замечания и повтори проверку, максимум три проверки одной задачи. Если лимит исчерпан, честно перечисли оставшиеся недостатки. Обязательный цикл качества: сделай черновой рендер, посмотри его через share_image/read_image, сравни с референсом, найди конкретные недостатки и исправь их. Проверь минимум общий ракурс и дополнительный ракурс/крупный план важных деталей; для модели, предназначенной для осмотра со всех сторон, проверь также обратную сторону. Отчёт qc.audit — диагностика базовой и evaluated-сетки, не доказательство красоты и не замена осмотру финального рендера. blender_run принимает необязательный asset_specification: назначение, точные имена mesh subjects, units (meters_per_unit), requirements и limits (размеры в метрах, бюджет evaluated triangles). В каждой папке запуска сохраняются asset-specification.json, quality.json и evidence.json с хешами файлов. Статусы pass/fail/pending/not_applicable относятся к отдельным gates: completed у фоновой задачи не означает готовность ассета. Визуальные, референсные, деформационные и экспортные проверки без реально выполненной валидации остаются pending; файл .blend, один рендер или записанный FBX их не подтверждают. Автоматическая ретопология и художественная корректность не гарантируются. Не называй результат отличным или завершённым, если рендер не открывался, есть неисправленные ошибки или объект всё ещё черновой.
Для персонажа раздели скульпт, деформационную топологию, UV, материалы, риг и анимационные клипы. Для лица проверь нейтральную позу, моргание, челюсть и крайние выражения. Используй отчёт inspection.json для проверки костей, весов, Shape Keys, Actions/NLA, камеры, экспозиции и света. Для анимации вызови blender_run с frames: выбери начало, выразительные позы и конец клипа, открой полученные PNG и проверь, что позы и силуэт действительно меняются. Для циклов проверь стык, для персонажа — отсутствие скольжения и провалов при деформации. Для экспорта в Unreal используй qc.export_unreal_fbx(path, objects, animation=True) для явно подготовленных мешей и рига. Сверь FPS, масштаб и совместимость скелета при импорте.
До итогового ответа сам отправь в чат реальные рендеры через share_image или снимки нужного приложения через take_screenshot. Пользователь может прикладывать фотографии — используй их как референсы, сохраняя цель и геометрию задачи. Передай .blend/целевой формат, необходимые текстуры и экспорт при запросе, используя present для готовых файлов. Коротко сообщи, что создано, что проверено и какие ограничения остались. Не обещай идеальное качество для любого объекта: добивайся его осмотром и доработкой.`;
export function apply(ctx){
  ctx.commands.register({
    definitionId: CommandDefinitionId('@qcoderi/team/blender'),
    name: 'blender',
    description: 'Проверить Blender и посмотреть возможности 3D локально',
    async handler({rawInput, signal}) {
      if (rawInput.trim()) return {kind:'error', text:'Введите /blender без аргументов.'};
      signal.throwIfAborted();
      const status = await blenderStatus();
      signal.throwIfAborted();
      return {
        kind: 'success',
        text: [
          status.installed ? `Установлен ${status.version}.` : 'Blender не найден.',
          'QCoderI может запускать Blender в фоне, сохранять редактируемый .blend, проверять геометрию и показывать рендеры с нескольких ракурсов.',
          'Для реалистичной головы нужны референсы спереди и в профиль, сетка с топологией под мимику, материалы кожи и глаз. Для анимации можно настроить кости головы, шеи, челюсти и глаз, а мимику сделать через Shape Keys. Качество проверяется на рендерах и тестовых выражениях лица.',
          'Для головы с ригом и анимациями используйте Skeletal Mesh и импорт FBX в редакторе Unreal. QCoderI проверяет параметры импортированного клипа и может показать кадр из viewport.',
        ].join('\n\n'),
      };
    },
  });
  ctx.systemPrompt.section({name:'qcoderi:3d-studio',order:97,text:STUDIO_PROMPT,interpolate:false});
  const output={schema:{type:'string'},render:(_args,text)=>[{type:'text',text}]};
  ctx.tools.register(defineTool({name:'blender_status',description:'Find installed Blender and report its actual version. Optional executable overrides discovery. No scene edits, no installation.',parameters:{executable:{type:'string'}},output,async execute(args,exec){requireProject(exec);return JSON.stringify(await blenderStatus(args.executable));}}));
  ctx.tools.register(defineTool({name:'blender_run',description:'Create/edit/inspect a real Blender scene in a separate background job. Write a Python project script first; it receives bpy, qc (studio/material/audit helpers) and QC_OUTPUT_DIR. Optional blend_file loads an existing saved project. Each run gets a new QCoderI-3D/run-* directory; original .blend is not overwritten by the wrapper. Scripts have normal user-level access. Saves scene.blend and geometry/material report, optionally render.png; persists quality.json gates and hashed evidence.json. Optional asset_specification defines requirements (metres, evaluated triangles). Job completion is not asset readiness; unperformed reviews remain pending. Inspect with job_output(wait:true), then share_image to evaluate the render. Does not change unsaved live Blender UI state.',parameters:{asset_specification:assetSpecificationParameter,script_file:{type:'string',description:'Workspace .py script; omit to inspect a saved blend.'},blend_file:{type:'string',description:'Workspace .blend file to load.'},executable:{type:'string'},render:{type:'boolean',description:'Render the active camera; if absent, creates a studio camera/light setup.'},views:{type:'boolean',description:'Also render front, side and back views for visual quality inspection; includes main render.'},frames:{type:'array',items:{type:'integer'},description:'Render up to eight chosen animation frames with the active camera and scene lighting.'},timeout_seconds:{type:'integer',description:'10–1800 seconds, default 600.'}},output,isConcurrencySafe:()=>false,async execute(args,exec){requireProject(exec);const prepared=await prepareBlender(exec.agent.session.header.cwd,args);exec.signal.throwIfAborted();const id=ctx.jobs.start({kind:'process',owner:exec.agent,label:'3D Studio · Blender',run:()=>startBlender(prepared)});return JSON.stringify({job_id:id,output_directory:prepared.out,report:prepared.report,quality_report:prepared.quality,evidence:prepared.evidenceFile,asset_specification:prepared.specificationFile,scene:prepared.scene,render:prepared.image,message:'Дождись job_output(wait:true), затем открой реальный рендер через share_image и исправь найденные недостатки.'});}}));
}
